UPDATE CATEGORY1 SET
ORD = ORD + 1 WHERE ORD >= ${cate_ord} AND ORD < ${cate_old_ord}
ORD = ORD - 1 WHERE ORD > ${cate_old_ord} AND ORD <= ${cate_ord}

 
		UPDATE CATEGORY1 SET NAME=#{cate_name} 
							,ORD =#{cate_ord} 
							,USE =#{cate_use} 
			WHERE 
					CODE='${cate_code} '
